def fold(title):
    """Sort and lookup key for a display title. Never longer, in UTF-8
    bytes, than its input."""
    out = []
    pending = False
    for ch in title:
        if ch in WHITESPACE:
            if out:
                pending = True
            continue
        if pending:
            out.append(" ")
            pending = False
        o = ord(ch)
        if 0x41 <= o <= 0x5A:
            ch = chr(o + 32)
        elif o >= 0xC0:
            ch = TABLE.get(ch, ch)
        out.append(ch)
    return "".join(out)


def fold_bytes(title):
    return fold(title).encode("utf-8")
